-- DebtLens v2 schema (MySQL 8 / TiDB).  Generated by scripts/export_schema.py — do not edit by hand.
-- Demo-1 tables keep their names: user, project, module, assignment, technical_debt, incident, root_cause, resolution.
SET NAMES utf8mb4;

CREATE TABLE embedding_cache (
	text_hash VARCHAR(64) NOT NULL, 
	vector BLOB NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (text_hash)
);

CREATE TABLE organization (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(120) NOT NULL, 
	slug VARCHAR(140) NOT NULL, 
	is_sandbox BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (slug)
);

CREATE TABLE project (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	org_id INTEGER NOT NULL, 
	project_name VARCHAR(160) NOT NULL, 
	project_key VARCHAR(12) NOT NULL, 
	description TEXT, 
	repository_url VARCHAR(300), 
	industry VARCHAR(60), 
	scenario_code VARCHAR(30), 
	is_sandbox BOOL NOT NULL, 
	sandbox_key VARCHAR(40), 
	expires_at DATETIME, 
	settings JSON, 
	next_incident_no INTEGER NOT NULL, 
	next_debt_no INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(org_id) REFERENCES organization (id) ON DELETE CASCADE, 
	UNIQUE (sandbox_key)
);
CREATE INDEX ix_project_expires_at ON project (expires_at);
CREATE INDEX ix_project_is_sandbox ON project (is_sandbox);
CREATE INDEX ix_project_org_id ON project (org_id);

CREATE TABLE user (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	org_id INTEGER NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	email VARCHAR(190), 
	password_hash VARCHAR(200), 
	`role` VARCHAR(20) NOT NULL, 
	title VARCHAR(160), 
	can_login BOOL NOT NULL, 
	is_active BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	last_login_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(org_id) REFERENCES organization (id) ON DELETE CASCADE, 
	UNIQUE (email)
);
CREATE INDEX ix_user_org_id ON user (org_id);

CREATE TABLE api_token (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	prefix VARCHAR(16) NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	revoked BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	last_used_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE, 
	UNIQUE (token_hash)
);
CREATE INDEX ix_api_token_user_id ON api_token (user_id);

CREATE TABLE audit_log (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER, 
	actor VARCHAR(160) NOT NULL, 
	`role` VARCHAR(20), 
	action VARCHAR(60) NOT NULL, 
	entity VARCHAR(60), 
	detail JSON, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);
CREATE INDEX ix_audit_log_created_at ON audit_log (created_at);
CREATE INDEX ix_audit_log_project_id ON audit_log (project_id);

CREATE TABLE cause_node (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
	label VARCHAR(300) NOT NULL, 
	normalized_label VARCHAR(300) NOT NULL, 
	category VARCHAR(20) NOT NULL, 
	embedding BLOB, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);
CREATE INDEX ix_cause_node_project_id ON cause_node (project_id);

CREATE TABLE module (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
	module_name VARCHAR(100) NOT NULL, 
	path VARCHAR(255), 
	description VARCHAR(400), 
	churn FLOAT NOT NULL, 
	complexity FLOAT NOT NULL, 
	loc INTEGER NOT NULL, 
	files INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (project_id, module_name), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);
CREATE INDEX ix_module_project_id ON module (project_id);

CREATE TABLE project_member (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	`role` VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (project_id, user_id), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE
);
CREATE INDEX ix_project_member_project_id ON project_member (project_id);
CREATE INDEX ix_project_member_user_id ON project_member (user_id);

CREATE TABLE remediation_plan (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
	budget_hours FLOAT NOT NULL, 
	method VARCHAR(20) NOT NULL, 
	selected_keys JSON NOT NULL, 
	total_value FLOAT NOT NULL, 
	total_hours FLOAT NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	notes TEXT, 
	approved_by VARCHAR(120), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);
CREATE INDEX ix_remediation_plan_project_id ON remediation_plan (project_id);

CREATE TABLE repo_scan (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
	source VARCHAR(15) NOT NULL, 
	repository VARCHAR(300), 
	commit_sha VARCHAR(64), 
	branch VARCHAR(120), 
	commits_analyzed INTEGER NOT NULL, 
	files_analyzed INTEGER NOT NULL, 
	window_days INTEGER, 
	warnings JSON, 
	scanned_by VARCHAR(120), 
	scanned_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);
CREATE INDEX ix_repo_scan_project_id ON repo_scan (project_id);

CREATE TABLE simulation_run (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
	kind VARCHAR(15) NOT NULL, 
	params JSON, 
	summary JSON, 
	run_by VARCHAR(120), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE
);
CREATE INDEX ix_simulation_run_project_id ON simulation_run (project_id);

CREATE TABLE assignment (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
	module_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	assigned_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE, 
	FOREIGN KEY(module_id) REFERENCES module (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE
);
CREATE INDEX ix_assignment_project_id ON assignment (project_id);

CREATE TABLE cause_edge (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
	source_node_id INTEGER NOT NULL, 
	target_node_id INTEGER NOT NULL, 
	relation VARCHAR(20) NOT NULL, 
	weight INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (source_node_id, target_node_id), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE, 
	FOREIGN KEY(source_node_id) REFERENCES cause_node (id) ON DELETE CASCADE, 
	FOREIGN KEY(target_node_id) REFERENCES cause_node (id) ON DELETE CASCADE
);
CREATE INDEX ix_cause_edge_project_id ON cause_edge (project_id);

CREATE TABLE file_metric (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
