	loc INTEGER NOT NULL, 
	authors INTEGER NOT NULL, 
	hotspot_score FLOAT NOT NULL, 
	last_modified DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE, 
	FOREIGN KEY(module_id) REFERENCES module (id) ON DELETE SET NULL
);
CREATE INDEX ix_file_metric_project_id ON file_metric (project_id);

CREATE TABLE incident (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
	module_id INTEGER, 
	incident_key VARCHAR(30) NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	description TEXT NOT NULL, 
	severity VARCHAR(10) NOT NULL, 
	status VARCHAR(15) NOT NULL, 
	reported_by INTEGER, 
	reporter_name VARCHAR(120), 
	reported_at DATETIME NOT NULL, 
	resolved_at DATETIME, 
	effort_hours FLOAT NOT NULL, 
	source VARCHAR(20) NOT NULL, 
	external_ref VARCHAR(300), 
	occurrences INTEGER NOT NULL, 
	group_label VARCHAR(30), 
	embedding BLOB, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (project_id, incident_key), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE, 
	FOREIGN KEY(module_id) REFERENCES module (id) ON DELETE SET NULL, 
	FOREIGN KEY(reported_by) REFERENCES user (id) ON DELETE SET NULL
);
CREATE INDEX ix_incident_project_id ON incident (project_id);
CREATE INDEX ix_incident_project_status ON incident (project_id, status);

CREATE TABLE module_dependency (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
	source_module_id INTEGER NOT NULL, 
	target_module_id INTEGER NOT NULL, 
	weight INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (source_module_id, target_module_id), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE, 
	FOREIGN KEY(source_module_id) REFERENCES module (id) ON DELETE CASCADE, 
	FOREIGN KEY(target_module_id) REFERENCES module (id) ON DELETE CASCADE
