CREATE INDEX ix_module_dependency_project_id ON module_dependency (project_id);

CREATE TABLE technical_debt (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	project_id INTEGER NOT NULL, 
	module_id INTEGER, 
	debt_key VARCHAR(30) NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	description TEXT NOT NULL, 
	category VARCHAR(20) NOT NULL, 
	priority VARCHAR(10) NOT NULL, 
	status VARCHAR(15) NOT NULL, 
	assigned_to INTEGER, 
	assignee_name VARCHAR(120), 
	root_cause_node_id INTEGER, 
	principal_hours FLOAT NOT NULL, 
	file_path VARCHAR(255), 
	source VARCHAR(20) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (project_id, debt_key), 
	FOREIGN KEY(project_id) REFERENCES project (id) ON DELETE CASCADE, 
	FOREIGN KEY(module_id) REFERENCES module (id) ON DELETE SET NULL, 
	FOREIGN KEY(assigned_to) REFERENCES user (id) ON DELETE SET NULL, 
	FOREIGN KEY(root_cause_node_id) REFERENCES cause_node (id) ON DELETE SET NULL
