CREATE INDEX ix_technical_debt_project_id ON technical_debt (project_id);

CREATE TABLE debt_dependency (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	debt_id INTEGER NOT NULL, 
	prerequisite_debt_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (debt_id, prerequisite_debt_id), 
	FOREIGN KEY(debt_id) REFERENCES technical_debt (id) ON DELETE CASCADE, 
	FOREIGN KEY(prerequisite_debt_id) REFERENCES technical_debt (id) ON DELETE CASCADE
);
CREATE INDEX ix_debt_dependency_debt_id ON debt_dependency (debt_id);

CREATE TABLE debt_incident (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	debt_id INTEGER NOT NULL, 
	incident_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (debt_id, incident_id), 
	FOREIGN KEY(debt_id) REFERENCES technical_debt (id) ON DELETE CASCADE, 
	FOREIGN KEY(incident_id) REFERENCES incident (id) ON DELETE CASCADE
);
CREATE INDEX ix_debt_incident_debt_id ON debt_incident (debt_id);
CREATE INDEX ix_debt_incident_incident_id ON debt_incident (incident_id);

CREATE TABLE resolution (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	incident_id INTEGER NOT NULL, 
	fixed_by INTEGER, 
