	PRIMARY KEY (id), 
	UNIQUE (incident_id), 
	FOREIGN KEY(incident_id) REFERENCES incident (id) ON DELETE CASCADE, 
	FOREIGN KEY(fixed_by) REFERENCES user (id) ON DELETE SET NULL
